                if stripped.startswith('from ') or stripped.startswith('import '):
                    top_imports.append(stripped)

            seen = {}
            for imp in top_imports:
                if imp in seen:
                    duplicates.append((filepath, imp))
                else:
                    seen[imp] = True

if duplicates:
